## WP2 — Muting a room or a user

### 2.1 Design decisions (do not deviate)

**A mute suppresses *notification*, never *delivery*.** A muted conversation still relays over the
WebSocket, still appends to the open thread, still increments its per-conversation unread count. It
does not fire a Web Push and does not contribute to the app-icon badge. This mirrors WhatsApp and
is what users expect.

**Mutes are keyed by target, not by conversation id.** The codebase has two different "conversation
key" spaces already — `Folder.convs` stores a bare peer uid, while `unread`/`Read.c` stores
`conv_id(a,b)` (`"a|b"` sorted) — and conflating them is the easiest bug to write here. Sidestep it:
a mute stores the *target* (a peer uid, or a room id) plus a kind. At every enforcement point you
already have both the viewer and the target in hand.

**A mute may expire.** `until: 0` means indefinite; otherwise a unix-ms timestamp. Expiry is
evaluated on read (`until === 0 || until > Date.now()`); no cleanup job. Offer 8 hours, 1 week, and
forever in the UI.

### 2.2 New file `src/lib/server/mute.ts`

```ts
import { ensure, upsert, scroll, remove, uuid_from, f, eq, ZV, type QEnv } from './qdrant';

export interface Mute {
    s: 'mu';
    ow: string;    // uid of the person who muted (indexed: 'ow')
    tg: string;    // target — peer uid for 'u', room id for 'r' (indexed: 'tg')
    k: 'u' | 'r';  // kind (indexed: 'k')
    until: number; // 0 = indefinite, else unix ms when the mute lapses
    d: number;     // created ts
}

// deterministic id: re-muting the same target overwrites rather than duplicating, and
// unmute is a delete of the same id — no read-then-delete round trip
const mute_id = (owner: string, target: string) => uuid_from(`mute:${owner}:${target}`);

export const is_active = (m: Mute, now = Date.now()): boolean => m.until === 0 || m.until > now;

export async function mute(
    env: QEnv,
    owner: string,
    target: string,
    kind: 'u' | 'r',
    until = 0
): Promise<Mute> {
    await ensure(env);
    const m: Mute = { s: 'mu', ow: owner, tg: target, k: kind, until, d: Date.now() };
    await upsert(env, [
        { id: await mute_id(owner, target), vector: ZV, payload: m as unknown as Record<string, unknown> }
    ]);
    return m;
}

export async function unmute(env: QEnv, owner: string, target: string): Promise<void> {
    await ensure(env);
    await remove(env, [await mute_id(owner, target)]);
}

/** every live mute this user owns */
export async function list_mutes(env: QEnv, owner: string, now = Date.now()): Promise<Mute[]> {
    await ensure(env);
    const pts = await scroll(env, f(eq('s', 'mu'), eq('ow', owner)), 500);
    return pts.map((p) => p.payload as unknown as Mute).filter((m) => is_active(m, now));
}

/** has `owner` muted `target`? */
export async function is_muted(
    env: QEnv,
    owner: string,
    target: string,
    now = Date.now()
): Promise<boolean> {
    await ensure(env);
    const pts = await scroll(env, f(eq('s', 'mu'), eq('ow', owner), eq('tg', target)), 1);
    const m = pts[0]?.payload as unknown as Mute | undefined;
    return !!m && is_active(m, now);
}

/**
 * Which of `uids` have muted `target`. One query for the whole room instead of one per
 * member — a 50-person room fanning out 50 scrolls would blow the subrequest budget.
 */
export async function muters_of(
    env: QEnv,
    target: string,
    uids: string[],
    now = Date.now()
): Promise<Set<string>> {
    if (!uids.length) return new Set();
    await ensure(env);
    const pts = await scroll(env, f(eq('s', 'mu'), eq('tg', target)), 1000);
    const candidates = new Set(uids);
    return new Set(
        pts
            .map((p) => p.payload as unknown as Mute)
            .filter((m) => is_active(m, now) && candidates.has(m.ow))
            .map((m) => m.ow)
    );
}

/** drop the uids that muted `target` — the shape every notify() call site needs */
export async function drop_muted(
    env: QEnv,
    target: string,
    uids: string[],
    now = Date.now()
): Promise<string[]> {
    const muted = await muters_of(env, target, uids, now);
    return uids.filter((u) => !muted.has(u));
}
```

### 2.3 New route `src/routes/api/mute/+server.ts`

```ts
import { json, error } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { env } from '$env/dynamic/private';
import { mute, unmute, list_mutes } from '$lib/server/mute';

export const GET: RequestHandler = async ({ locals }) => {
    if (!locals.user) throw error(401, 'auth');
    return json({ mutes: await list_mutes(env, locals.user.id) });
};

// POST { target, kind: 'u'|'r', until?: number }
export const POST: RequestHandler = async ({ request, locals }) => {
    if (!locals.user) throw error(401, 'auth');
    const b = (await request.json().catch(() => null)) as {
        target?: string;
        kind?: string;
        until?: number;
    } | null;
    const target = b?.target?.trim();
    const kind = b?.kind;
    if (!target) throw error(400, 'target required');
    if (kind !== 'u' && kind !== 'r') throw error(400, 'kind must be u or r');
    if (target === locals.user.id) throw error(400, 'cannot mute yourself');
    const until = typeof b?.until === 'number' && b.until > Date.now() ? b.until : 0;
    return json({ mute: await mute(env, locals.user.id, target, kind, until) });
};

// DELETE ?target=X
export const DELETE: RequestHandler = async ({ url, locals }) => {
    if (!locals.user) throw error(401, 'auth');
    const target = url.searchParams.get('target')?.trim();
    if (!target) throw error(400, 'target required');
    await unmute(env, locals.user.id, target);
    return json({ ok: true });
};
```

Note the self-mute guard: a user muting themselves would silently suppress nothing (you never
notify the sender) but would show up in their settings list as a confusing entry.

### 2.4 Enforce at every `notify()` call site

There are exactly two. Grep to confirm before and after: `grep -rn "notify(" src/lib src/routes`.

**Site 1 — `src/routes/api/send/+server.ts`, group branch (~line 99).** The target of a room mute is
the room id:

```ts
const targets = await drop_muted(env, group, undelivered.filter((u) => u !== me.id));
```

**Site 2 — same file, DM branch (~line 120).** The target of a user mute is the sender's uid:

```ts
if (undelivered.includes(to) && !(await is_muted(env, to, me.id))) {
    // …existing push…
}
```

**Site 3 — `src/lib/server/scheduled.ts:67`.** Read that function; it dispatches queued messages
through the same relay+notify path. Apply the identical filter there: room sends via `drop_muted`,
DM sends via `is_muted`. A scheduled message that ignores a mute is the same bug arriving late.

### 2.5 Exclude muted conversations from the badge, not from the list

`src/lib/server/unread.ts`. `unread_by_conv` keeps returning every conversation's count — the chat
list still shows "3" next to a muted thread. Only the *total* that drives the app icon badge
changes.

Add an optional muted-conv filter to `total_unread`:

```ts
export async function total_unread(
    env: QEnv,
    uid: string,
    group_convs: string[] = []
): Promise<number> {
    const by_conv = await unread_by_conv(env, uid, group_convs);
    const mutes = await list_mutes(env, uid);
    // Mute targets are peer uids / room ids; unread keys are conv ids. Translate once.
    const silent = new Set(
        mutes.map((m) => (m.k === 'r' ? group_conv_id(m.tg) : conv_id(uid, m.tg)))
    );
    return Object.entries(by_conv)
        .filter(([conv]) => !silent.has(conv))
        .reduce((n, [, count]) => n + count, 0);
}
```

Import `conv_id` and `group_conv_id` from `./chat`. **Watch for an import cycle:** `chat.ts` does
`export { get_user_name } from './user'` and imports from `./qdrant` and `./or` — it does not import
`unread.ts`, so `unread.ts → chat.ts` is safe. Verify with `pnpm test` (a cycle shows up as an
`undefined is not a function` at import time).

`src/routes/api/read/+server.ts` GET should return both numbers so the client can render a muted
thread's count without badging it:

```ts
return json({ total, by_conv, muted: [...silent] });
```

Extract the conv-key translation into an exported helper in `mute.ts` so both files use one
implementation:

```ts
export function muted_convs(uid: string, mutes: Mute[]): string[] { … }
```

